  "d.1ou7t1x": "EPEPO",
  "d.1pfk73q": "Oshikaha otashi tameke, omapulo konima. Omapari gomaleisa gamabali, omagan omagoshi gamabali nomaroketi omagoshi omulongo nambali, ne gomo ge ya yelekwa yo yene.",
  "d.1pg1xjs": "OMUTWALI GWIINIMA",
